public async IAsyncEnumerable<ChatCompletionChunk> GetChatCompletionStreamAsync(
    ChatCompletionRequest request,
    [EnumeratorCancellation] CancellationToken cancellationToken = default)
{
    // 1. Build provider-specific request (reuse existing BuildRequest logic)
    // 2. Set stream = true and stream_options
    // 3. Call _client.PostStreamAsync(endpoint, request, ct)
    // 4. Deserialize each JSON line into OpenAiStreamChunk or OpenAiResponsesStreamEvent
    // 5. Map to ChatCompletionChunk and yield

    // For Chat Completions API:
    await foreach (var json in _client.PostStreamAsync(endpoint, providerRequest, cancellationToken))
    {
        var chunk = JsonSerializer.Deserialize<OpenAiStreamChunk>(json, _jsonOptions);
        if (chunk?.Choices is { Count: > 0 })
        {
            var choice = chunk.Choices[0];
            var toolDelta = MapToolCallDelta(choice.Delta?.ToolCalls);
            yield return new ChatCompletionChunk(
                Content: choice.Delta?.Content ?? string.Empty,
                FinishReason: choice.FinishReason,
                Model: chunk.Model,
                PromptTokens: chunk.Usage?.PromptTokens,
                CompletionTokens: chunk.Usage?.CompletionTokens,
                ToolCallDelta: toolDelta);
        }
        else if (chunk?.Usage is not null)
        {
            // Usage-only final chunk (when stream_options.include_usage is true)
            yield return new ChatCompletionChunk(
                Content: string.Empty,
                PromptTokens: chunk.Usage.PromptTokens,
                CompletionTokens: chunk.Usage.CompletionTokens);
        }
    }

    // For Responses API (GPT-5): different event types
    // Parse "type" field to determine event kind
    // "response.output_text.delta" → content delta
    // "response.completed" → final event with usage
}
```

